import {STORAGE,COURSES,WORDS,text,defaults,fresh,solve,validate,record,copy} from './curriculum-model.js';

export function createCurriculum(adapter){
 const lang=document.documentElement.lang==='en'?'en':'ko',t=pair=>text(pair,lang),w=key=>t(WORDS[key]||key);
 let state=fresh(),active=false,phase='ready',timer=0,notice='',saved=true;
 const params=new URLSearchParams(location.search);
 try{const raw=localStorage.getItem(STORAGE);if(raw)state=validate(JSON.parse(raw))}catch{notice=lang==='en'?'Previous course record could not be loaded.':'이전 과정 기록을 불러오지 못했습니다.'}
 if(COURSES[params.get('course')])state.course=params.get('course');else if(['elementary','middle','high'].includes(params.get('school')))state.course=params.get('school')==='high'?'physics':params.get('school');
 const root=document.createElement('div');root.id='curriculum';document.getElementById('ui').append(root);root.hidden=true;
 const el=(tag,parent,content,cls)=>{const e=document.createElement(tag);if(content!==undefined)e.textContent=content;if(cls)e.className=cls;parent.append(e);return e};
 const header=el('header',root,undefined,'course-header');el('span',header,w('title'),'course-brand');const bands=el('nav',header);bands.setAttribute('aria-label',w('bands'));
 const toolbar=el('div',header,undefined,'course-toolbar');
 const icon=(path)=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+path+'"/></svg>';
 function button(parent,label,fn,id,cls){const b=el('button',parent,label,cls);b.type='button';if(id)b.id=id;b.addEventListener('click',fn);return b}
 const guide=button(toolbar,'',()=>window.open('guide.html?lang='+lang,'_blank','noopener'));guide.innerHTML=icon('M4 4h6l2 2 2-2h6v15h-6l-2 2-2-2H4Z M12 6v15');guide.setAttribute('aria-label',w('guide'));guide.title=w('guide');
 const share=button(toolbar,'',()=>{if(window.__site?.share)return window.__site.share();const url=new URL(location.href);url.searchParams.set('course',state.course);if(navigator.share)navigator.share({title:w('title'),url:url.href}).catch(()=>{});else navigator.clipboard?.writeText(url.href).then(()=>{notice=lang==='en'?'Link copied.':'공유 주소를 복사했습니다.';render()}).catch(()=>{})});share.innerHTML=icon('M15 7 9 11m0 2 6 4 M8 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M21 5a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M21 19a3 3 0 1 1-6 0 3 3 0 0 1 6 0');share.setAttribute('aria-label',w('share'));share.title=w('share');
 const panel=el('section',root,undefined,'course-panel');panel.setAttribute('aria-label',w('adjust'));
 const chooser=el('div',panel,undefined,'course-chooser');const route=el('p',panel,undefined,'course-route');const title=el('h1',panel);const instruction=el('p',panel,undefined,'course-instruction');
 const controls=el('div',panel,undefined,'course-controls');const scaleActions=el('div',panel,undefined,'course-scale-actions');const primary=button(panel,w('run'),run,'course-run','course-primary');
 const output=el('div',panel,undefined,'course-output');output.setAttribute('role','status');output.setAttribute('aria-live','polite');const message=el('p',panel,undefined,'course-message');message.setAttribute('role','status');
 const sequence=el('div',panel,undefined,'course-sequence');
 const sceneLabel=el('div',root,undefined,'course-scene-label');const sceneName=el('strong',sceneLabel),sceneCaption=el('span',sceneLabel);
 const notebook=el('details',root,undefined,'course-notebook');notebook.id='course-notebook';const summary=el('summary',notebook),recordHeading=el('span',summary),count=el('span',summary);const notebookBody=el('div',notebook,undefined,'course-notebook-body');
 const recordList=el('div',notebookBody,undefined,'course-record-list');const evidence=el('div',notebookBody,undefined,'course-evidence');const noteLabel=el('label',evidence,w('note'));noteLabel.htmlFor='course-note';const note=el('textarea',evidence);note.id='course-note';note.rows=3;note.maxLength=4000;note.placeholder=w('placeholder');note.addEventListener('input',()=>{experiment().note=note.value;save()});
 button(evidence,w('saveNote'),()=>{save();notice=w(saved?'saved':'saveFail');message.textContent=notice},'course-save-note');const recordTools=el('div',notebookBody,undefined,'course-record-tools');button(recordTools,w('export'),download,'course-export');button(recordTools,w('reset'),reset,'course-reset');
 const footer=el('small',root,w('model'),'course-footer');
 const course=()=>COURSES[state.course],session=()=>state.courses[state.course],activity=()=>course().activities.find(a=>a.id===session().activity),experiment=()=>session().experiments[activity().id];
 function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));saved=true}catch{saved=false}}
 function currentResult(){return solve(activity().id,experiment().inputs,experiment())}
 function prepare(){const result=currentResult();adapter.prepare(result);adapter.view(activity().id,{...experiment().inputs,...experiment()},result,0,false);}
 function chooseCourse(id){if(!COURSES[id]||phase==='running')return;state.course=id;phase='ready';timer=0;notice='';notebook.open=false;save();prepare();render();panel.scrollTop=0;}
 function chooseActivity(id){if(!course().activities.some(a=>a.id===id)||phase==='running')return;session().activity=id;phase='ready';timer=0;notice='';save();prepare();render();panel.scrollTop=0;}
 function set(key,value){if(phase==='running')return;const c=activity().controls.find(c=>c.key===key);if(!c)return;const e=experiment();if(c.options){if(!c.options.some(o=>o[0]===value))return}else value=Math.min(c.max,Math.max(c.min,Math.round((Number(value)-c.min)/c.step)*c.step+c.min));e.inputs[key]=value;phase='ready';notice='';save();prepare();render();}
 function zero(){if(activity().id!=='scale'||experiment().placed)return;experiment().zeroed=true;phase='ready';notice=w('zeroDone');save();prepare();render();}
 function place(){if(activity().id!=='scale')return;experiment().placed=!experiment().placed;phase='ready';save();prepare();render();}
 function run(){if(!active||phase==='running'||experiment().trials.length>=100)return;if(activity().id==='scale'&&(!experiment().zeroed||!experiment().placed)){notice=w('zeroNeed');render();return}prepare();phase='running';timer=0;notice='';if(currentResult().dynamic)adapter.run();render();}
 function finish(){adapter.stop();record(state);phase='result';save();render();if(innerWidth>980)output.scrollIntoView({block:'nearest',behavior:'instant'});}
 function tick(dt){if(!active)return;const r=currentResult();if(phase==='running'){timer=Math.min(1.2,timer+dt);if(r.dynamic)adapter.limit(r);if(timer>=1.2-1e-9)finish()}adapter.view(activity().id,{...experiment().inputs,zeroed:experiment().zeroed,placed:experiment().placed},r,timer/1.2,phase==='result');}
 function download(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='force-lab-courses.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function reset(){const e=experiment();Object.assign(e,{inputs:defaults(activity()),trials:[],note:'',zeroed:false,placed:false});phase='ready';notice=w('resetDone');save();prepare();render();}
 function metricText(m){const v=m.value===null?'—':Number.isInteger(m.value)?m.value:Math.abs(m.value)<1e-8?'0':m.value.toFixed(2);return v+(m.unit?' '+(m.unit==='relative'?(lang==='en'?'units':'칸'):m.unit):'');}
 function controlsText(inputs,a=activity()){return a.controls.map(c=>w(c.label)+': '+(c.options?w(c.options.find(o=>o[0]===inputs[c.key])?.[1]):inputs[c.key]+(c.unit?' '+c.unit:''))).join(' · ')}
 function resultText(result){if(activity().id==='design')return lang==='en'?(result.metrics.find(m=>m.key==='displacement').value<=1?'Stops before the line':'Passes the line'):(result.metrics.find(m=>m.key==='displacement').value<=1?'목표선 앞에서 멈춤':'목표선을 지나감');return w(result.outcome);}
 function render(){if(!active)return;const focused=document.activeElement?.id,selStart=document.activeElement===note?note.selectionStart:null;const a=activity(),e=experiment(),r=currentResult();
  bands.replaceChildren();for(const id of ['elementary','middle','high']){const b=button(bands,w(id),()=>chooseCourse(id==='high'?(COURSES[state.course].band==='high'?state.course:'physics'):id),'course-band-'+id);b.setAttribute('aria-pressed',String(course().band===id));b.disabled=phase==='running';}
  chooser.replaceChildren();if(course().band==='high'){const l=el('label',chooser,w('choose'));l.htmlFor='course-high';const select=el('select',chooser);select.id='course-high';for(const id of ['physics','mechanics']){const o=el('option',select,w(id));o.value=id}select.value=state.course;select.disabled=phase==='running';select.addEventListener('change',()=>chooseCourse(select.value));}
  const label=el('label',chooser,w('activity'));label.htmlFor='course-activity';const select=el('select',chooser);select.id='course-activity';for(const item of course().activities){const o=el('option',select,t(item.title));o.value=item.id}select.value=a.id;select.disabled=phase==='running';select.addEventListener('change',()=>chooseActivity(select.value));
  const idx=course().activities.indexOf(a);route.textContent=t(course().label)+'  ·  '+(idx+1)+' / '+course().activities.length;title.textContent=t(a.title);instruction.textContent=t(a.instruction);sceneName.textContent=t(a.title);sceneCaption.textContent=['friction','design'].includes(a.id)?(lang==='en'?'Sliding friction model · initial speed 1.5 m/s':'미끄럼 마찰 모형 · 출발 속도 1.5 m/s'):a.rig==='cart'?w('cartModel'):w('model');
  controls.replaceChildren();for(const c of a.controls){const row=el('div',controls,undefined,'course-control'),l=el('label',row,w(a.id==='tools'&&c.key==='length'&&e.inputs.tool==='lever'?'arm':c.label));l.htmlFor='course-input-'+c.key;
   if(c.options){const s=el('select',row);s.id=l.htmlFor;for(const [value,key]of c.options){const o=el('option',s,w(key));o.value=String(value)}s.value=String(e.inputs[c.key]);s.disabled=phase==='running';s.addEventListener('change',()=>set(c.key,c.options.find(o=>String(o[0])===s.value)[0]));}
   else {const stepper=el('div',row,undefined,'course-stepper'),minus=button(stepper,'−',()=>set(c.key,e.inputs[c.key]-c.step),'course-minus-'+c.key);minus.setAttribute('aria-label',w(c.label)+(lang==='en'?' decrease':' 줄이기'));minus.disabled=phase==='running'||e.inputs[c.key]<=c.min;const value=el('output',stepper,e.inputs[c.key]+(c.unit?' '+c.unit:''));value.id=l.htmlFor;value.setAttribute('aria-label',w(c.label));const plus=button(stepper,'+',()=>set(c.key,e.inputs[c.key]+c.step),'course-plus-'+c.key);plus.setAttribute('aria-label',w(c.label)+(lang==='en'?' increase':' 늘리기'));plus.disabled=phase==='running'||e.inputs[c.key]>=c.max;}
  }
  scaleActions.replaceChildren();if(a.id==='scale'){const z=button(scaleActions,w('zero'),zero,'course-zero');z.disabled=e.placed||phase==='running';const p=button(scaleActions,w(e.placed?'remove':'onScale'),place,'course-place');p.disabled=phase==='running';}
  primary.textContent=w(phase==='running'?'running':r.dynamic?'run':'measure');primary.disabled=phase==='running'||e.trials.length>=100||(a.id==='scale'&&(!e.zeroed||!e.placed));
  output.replaceChildren();if(phase==='result'){el('span',output,w('result'),'course-output-label');el('strong',output,resultText(r),'course-outcome');const shown=r.metrics.slice(0,['tools','gravity','elastic','buoyancy'].includes(a.id)||course().band==='high'?3:2);for(const m of shown){const line=el('div',output,undefined,'course-metric');el('span',line,w(m.key));el('strong',line,metricText(m))}if(a.id==='tools')el('small',output,lang==='en'?'Force comparison: 1 unit = direct lift of 1 kg.':'힘 비교: 1칸은 1 kg 물체를 그냥 들 때의 힘입니다.');}
  else el('p',output,w(phase==='running'?'running':'ready'));
  message.textContent=!saved?w('saveFail'):notice||(phase==='result'?w('compare'):'');
  sequence.replaceChildren();const prev=button(sequence,'← '+w('previous'),()=>chooseActivity(course().activities[idx-1].id));prev.disabled=idx===0||phase==='running';const next=button(sequence,w('next')+' →',()=>chooseActivity(course().activities[idx+1].id));next.disabled=idx===course().activities.length-1||phase==='running';
  recordHeading.textContent=w('record')+' · '+t(a.title);count.textContent=e.trials.length+' '+w('count');recordList.replaceChildren();if(!e.trials.length)el('p',recordList,w('empty'));
  else {const table=el('table',recordList);const head=el('thead',table),hr=el('tr',head);for(const key of ['trial','condition','observation'])el('th',hr,w(key));const body=el('tbody',table);for(const tr of e.trials){const row=el('tr',body);el('td',row,String(tr.id));el('td',row,controlsText(tr.inputs));const cell=el('td',row);el('span',cell,resultText(tr.result));const d=el('details',cell);el('summary',d,w('detail'));for(const m of tr.result.metrics)el('div',d,w(m.key)+': '+metricText(m));}}
  noteLabel.textContent=t(a.prompt);note.value=e.note;note.disabled=phase==='running';evidence.hidden=e.trials.length===0;recordTools.querySelector('#course-reset').disabled=phase==='running';if(focused){const target=document.getElementById(focused);if(target&&!target.disabled)target.focus({preventScroll:true})}if(selStart!==null)note.setSelectionRange(selStart,selStart);
 }
 function start(){adapter.enter();active=true;root.hidden=false;document.body.classList.add('curriculum');document.getElementById('scene').setAttribute('aria-label',w('scene'));prepare();render();save();return state;}
 function deactivate(){active=false;root.hidden=true;document.body.classList.remove('curriculum');adapter.stop();adapter.exit();}
 return {start,deactivate,tick,chooseCourse,chooseActivity,set,run,zero,place,reset,download,get active(){return active},get phase(){return phase},get state(){return state},report:()=>copy(state)};
}
